code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y+dy, x+dx
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] != 0 and (yy,xx) not in seen:
                        seen.add((yy,xx))
                        stack.append((yy,xx))
            colors = {}
            for y,x in cells:
                colors.setdefault(grid[y][x], []).append((y,x))
            ordered = sorted(colors, key=lambda col: -((max(y for y,x in colors[col])-min(y for y,x in colors[col])+1) * (max(x for y,x in colors[col])-min(x for y,x in colors[col])+1)))
            remap = {ordered[i]: ordered[len(ordered)-1-i] for i in range(len(ordered))}
            for y,x in cells:
                out[y][x] = remap[grid[y][x]]
    return out
'''
